17	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
18	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
19	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
20	 */
21	@Profile("harness")
22	@RestController
23	@RequestMapping("/__test__")
24	public class TestSupportController {
25	
26	    private final Audit audit;
27	    private final JdbcTemplate jdbc;
28	
29	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
30	        this.audit = audit;
31	        this.jdbc = jdbc;
32	    }
33	
34	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
35	    @PostMapping("/reset")
36	    public void reset() {
37	        audit.clear();
38	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
39	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
40	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
49	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
50	        jdbc.execute("TRUNCATE TABLE dashboard_settings");
51	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	    }
