54	    /**
55	     * Parse a note's {@code at} stamp, accepting either a full ISO offset date-time or a plain
56	     * date (treated as the start of that day in UTC), so a fixture can write either form.
57	     */
58	    private static OffsetDateTime parseInstant(String value) {
59	        return value.contains("T")
60	                ? OffsetDateTime.parse(value)
61	                : LocalDate.parse(value).atStartOfDay().atOffset(ZoneOffset.UTC);
62	    }
