64	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
65	    @PostMapping("/seed")
66	    @SuppressWarnings("unchecked")
67	    public void seed(@RequestBody Map<String, Object> fixture) {
68	        // The dashboard measures invoice "overdue" against a fixed reference date; store it when the
69	        // fixture supplies one so the home-screen count is deterministic.
70	        Object asOf = fixture.get("asOf");
71	        if (asOf != null) {
72	            jdbc.update("INSERT INTO dashboard_settings (id, as_of) VALUES (1, ?)", asOf.toString());
73	        }
74	
75	        List<Map<String, Object>> clients =
76	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
77	        long maxClientId = 0;
78	        for (Map<String, Object> client : clients) {
79	            long id = ((Number) client.get("id")).longValue();
80	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
81	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
