91	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
92	        long maxProjectId = 0;
93	        for (Map<String, Object> project : projects) {
94	            long id = ((Number) project.get("id")).longValue();
95	            long clientId = ((Number) project.get("clientId")).longValue();
96	            String status = (String) project.getOrDefault("status", "ACTIVE");
